/**
 * Plugin hook runner for server-side plugins
 * Delegates to shared @datafn/core hook runner with env: "server"
 */

import type { DatafnPlugin, DatafnHookContext, HookError } from "../core-types.js";
import { runBeforeHook, runAfterHook } from "@datafn/core";
import type { DatafnLogger } from "../logger.js";

export type { HookError };

export async function runBeforeQuery(
  query: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any; context?: unknown },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; query: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema, context: ctx.context };
  const result = await runBeforeHook(plugins, "server", "beforeQuery", hookCtx, query);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, query: result.value };
}

export async function runBeforeSearch(
  search: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any; context?: unknown },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; search: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema, context: ctx.context };
  const result = await runBeforeHook(plugins, "server", "beforeSearch", hookCtx, search);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, search: result.value };
}

export async function runAfterQuery(
  query: unknown,
  result: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
  logger?: DatafnLogger,
): Promise<unknown> {
  // LOW-006: Capture return value from afterQuery hooks so plugins can transform/redact results.
  // runAfterHook ignores return values; we implement the loop inline to capture them.
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  let current = result;
  const filtered = plugins.filter((p) => p.runsOn.includes("server"));
  for (const plugin of filtered) {
    const hook = plugin.afterQuery as ((ctx: DatafnHookContext, query: unknown, result: unknown) => Promise<unknown> | unknown) | undefined;
    if (!hook) continue;
    try {
      const returned = await hook(hookCtx, query, current);
      if (returned !== undefined) current = returned;
    } catch (err) {
      logger?.error("Plugin afterQuery error", { plugin: plugin.name, error: String(err), operation: "plugin" });
    }
  }
  return current;
}

export async function runBeforeMutation(
  mutation: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; mutation: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  const result = await runBeforeHook(plugins, "server", "beforeMutation", hookCtx, mutation);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, mutation: result.value };
}

export async function runAfterMutation(
  mutation: unknown,
  result: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
): Promise<void> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  await runAfterHook(plugins, "server", "afterMutation", hookCtx, mutation, result);
}

export async function runBeforeSync(
  phase: "seed" | "clone" | "pull" | "push" | "reconcile",
  payload: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
): Promise<{ ok: true; payload: unknown } | { ok: false; error: HookError }> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  const result = await runBeforeHook(plugins, "server", "beforeSync", hookCtx, payload, [phase]);
  if (!result.ok) return { ok: false, error: result.error };
  return { ok: true, payload: result.value };
}

export async function runAfterSync(
  phase: "seed" | "clone" | "pull" | "push" | "reconcile",
  payload: unknown,
  result: unknown,
  ctx: { plugins: DatafnPlugin[]; schema: any },
  plugins: DatafnPlugin[],
): Promise<void> {
  const hookCtx: DatafnHookContext = { env: "server", schema: ctx.schema };
  await runAfterHook(plugins, "server", "afterSync", hookCtx, payload, result, [phase]);
}

/**
 * Plugin hook runner for client-side plugins
 * Delegates to shared @datafn/core hook runner with env: "client"
 */

import type { DatafnPlugin, DatafnHookContext, DatafnSchema } from "@datafn/core";
import { runBeforeHook, runAfterHook } from "@datafn/core";

export async function runBeforeQuery(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  query: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  const result = await runBeforeHook(plugins, "client", "beforeQuery", ctx, query);
  if (!result.ok) throw result.error;
  return result.value;
}

export async function runAfterQuery(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  query: unknown,
  queryResult: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  await runAfterHook(plugins, "client", "afterQuery", ctx, query, queryResult);
  return queryResult;
}

export async function runBeforeMutation(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  mutation: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  const result = await runBeforeHook(plugins, "client", "beforeMutation", ctx, mutation);
  if (!result.ok) throw result.error;
  return result.value;
}

export async function runAfterMutation(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  mutation: unknown,
  mutationResult: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  await runAfterHook(plugins, "client", "afterMutation", ctx, mutation, mutationResult);
  return mutationResult;
}

export async function runBeforeSync(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  phase: "seed" | "clone" | "pull" | "push" | "cloneUp" | "reconcile",
  payload: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  // beforeSync signature: (ctx, phase, payload) — phase is a pre-arg
  const result = await runBeforeHook(plugins, "client", "beforeSync", ctx, payload, [phase]);
  if (!result.ok) throw result.error;
  return result.value;
}

export async function runAfterSync(
  plugins: DatafnPlugin[],
  schema: DatafnSchema,
  phase: "seed" | "clone" | "pull" | "push" | "cloneUp" | "reconcile",
  payload: unknown,
  syncResult: unknown,
): Promise<unknown> {
  const ctx: DatafnHookContext = { env: "client", schema };
  // afterSync signature: (ctx, phase, payload, result) — phase is a pre-arg
  await runAfterHook(plugins, "client", "afterSync", ctx, payload, syncResult, [phase]);
  return syncResult;
}

import { source } from "@/lib/source";
import {
  DocsPage,
  DocsBody,
  DocsDescription,
  DocsTitle,
} from "fumadocs-ui/page";
import { notFound } from "next/navigation";
import defaultMdxComponents from "fumadocs-ui/mdx";
import { Mermaid } from "@/components/mdx/mermaid";
import type { ComponentType } from "react";
import { LLMCopyButton, ViewOptions } from '@/components/ai/page-actions';
import { gitConfig } from "@/app/layout.config";

type LoadedDocsPageData = {
  body: ComponentType<{ components?: Record<string, unknown> }>;
  description?: string;
  full?: boolean;
  title: string;
  toc?: unknown;
};

export default async function Page(props: {
  params: Promise<{ slug?: string[] }>;
}) {
  const params = await props.params;
  const page = source.getPage(params.slug);
  if (!page) notFound();

  const data = page.data as typeof page.data & LoadedDocsPageData;
  const { body: MDX, description, full, title } = data;
  const toc = Array.isArray(data.toc) ? data.toc : [];
  const rawMarkdownBase =
    process.env.CLOUDFLARE_DOCS_DEPLOY === "1"
      ? "/docs/api/docs/raw"
      : "/api/docs/raw";
  const rawMarkdownUrl = `${rawMarkdownBase}/${page.path}`;

  return (
    <DocsPage
      toc={toc}
      full={full}
      editOnGithub={{
        owner: gitConfig.user,
        repo: gitConfig.repo,
        path: `datafn/docs/content/docs/${page.path}`,
        sha: gitConfig.branch,
      }}
    >
      <DocsTitle>{title}</DocsTitle>
      <DocsDescription className="mb-0">{description}</DocsDescription>
      <div className="flex flex-row gap-2 items-center border-b pb-6">
        <LLMCopyButton markdownUrl={rawMarkdownUrl} />
        <ViewOptions
          markdownUrl={rawMarkdownUrl}
          githubUrl={`https://github.com/${gitConfig.user}/${gitConfig.repo}/blob/${gitConfig.branch}/datafn/docs/content/docs/${page.path}`}
        />
      </div>
      <DocsBody>
        <MDX components={{ ...defaultMdxComponents, Mermaid }} />
      </DocsBody>
    </DocsPage>
  );
}

export function generateStaticParams() {
  return source.generateParams();
}

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import {
  docsProducts,
  hasDocsPackage,
  normalizeEnvironment,
  parseProducts,
  repoRoot,
  workerName,
} from "./config.mjs";

const environment = normalizeEnvironment(process.argv[2] ?? "dev");
if (!environment) {
  console.error("Usage: node scripts/cloudflare-docs/deploy.mjs <dev|live> [--products=datafn,searchfn,authfn|all] [--dry-run] [--skip-build]");
  process.exit(1);
}

const products = parseProducts(getArgValue("products") ?? "all", { existingOnly: false });
const dryRun = hasFlag("dry-run");
const skipBuild = hasFlag("skip-build");

for (const productId of products) {
  if (!hasDocsPackage(productId)) {
    throw new Error(`Cannot deploy ${productId} docs because ${docsProducts[productId].docsDir}/package.json does not exist.`);
  }

  const product = docsProducts[productId];
  const docsDir = path.join(repoRoot, product.docsDir);
  const name = workerName(productId, environment);

  if (!skipBuild) {
    buildDocs(product, docsDir, environment);
  }

  if (product.kind === "next-static") {
    deployNextStatic(productId, docsDir, name);
  } else if (product.kind === "sveltekit-cloudflare") {
    deploySvelteKitCloudflare(docsDir, name);
  } else {
    throw new Error(`Unsupported docs deployment kind: ${product.kind}`);
  }
}

function buildDocs(product, docsDir, environment) {
  const assetsOrigin = product.kind === "sveltekit-cloudflare"
    ? `https://${product.hosts[environment]}`
    : `https://${product.hosts[environment]}/docs`;

  run("npx", ["turbo", "run", "build", `--filter=${product.packageName}...`, "--env-mode=loose"], {
    cwd: repoRoot,
    env: {
      CLOUDFLARE_DOCS_DEPLOY: "1",
      CLOUDFLARE_DOCS_ASSETS_ORIGIN: assetsOrigin,
      NEXT_PUBLIC_SITE_URL: `https://${product.hosts[environment]}`,
      NODE_ENV: "production",
      NEXT_TELEMETRY_DISABLED: "1",
    },
  });
}

function deployNextStatic(productId, docsDir, name) {
  const outDir = path.join(docsDir, "out");
  const docsIndex = path.join(outDir, "docs", "index.html");
  assertFile(docsIndex, `${productId} docs static export did not produce ${path.relative(repoRoot, docsIndex)}`);

  const stageDir = path.join(docsDir, ".cloudflare-docs-assets");
  fs.rmSync(stageDir, { recursive: true, force: true });
  fs.mkdirSync(stageDir, { recursive: true });
  copyDir(outDir, stageDir);

  for (const name of ["llms.txt", "llms-full.txt"]) {
    const source = path.join(outDir, name);
    assertFile(source, `Missing generated docs artifact: ${source}`);
    fs.mkdirSync(path.join(stageDir, "docs"), { recursive: true });
    fs.copyFileSync(source, path.join(stageDir, "docs", name));
  }

  const nextAssets = path.join(outDir, "_next");
  if (fs.existsSync(nextAssets)) {
    copyDir(nextAssets, path.join(stageDir, "docs", "_next"));
  }

  const apiAssets = path.join(outDir, "api");
  if (fs.existsSync(apiAssets)) {
    copyDir(apiAssets, path.join(stageDir, "docs", "api"));
  }

  const wranglerConfig = writeWranglerConfig(docsDir, {
    name,
    assetsDirectory: ".cloudflare-docs-assets",
  });
  runWranglerDeploy(docsDir, wranglerConfig, name);
}

function deploySvelteKitCloudflare(docsDir, name) {
  const cloudflareOutputDir = path.join(docsDir, ".svelte-kit", "cloudflare");
  const workerEntry = path.join(cloudflareOutputDir, "_worker.js");
  assertFile(workerEntry, `SvelteKit Cloudflare build did not produce ${path.relative(repoRoot, workerEntry)}`);
  fs.writeFileSync(path.join(cloudflareOutputDir, ".assetsignore"), "_worker.js\n");

  const wranglerConfig = writeWranglerConfig(docsDir, {
    name,
    main: ".svelte-kit/cloudflare/_worker.js",
    assetsDirectory: ".svelte-kit/cloudflare",
    compatibilityFlags: ["nodejs_compat"],
  });
  runWranglerDeploy(docsDir, wranglerConfig, name);
}

function writeWranglerConfig(docsDir, options) {
  const configPath = path.join(docsDir, ".cloudflare-docs-wrangler.jsonc");
  const config = {
    name: options.name,
    compatibility_date: "2026-05-18",
    workers_dev: true,
    observability: {
      enabled: true,
    },
    assets: {
      directory: options.assetsDirectory,
    },
  };
  if (options.main) config.main = options.main;
  if (options.compatibilityFlags) config.compatibility_flags = options.compatibilityFlags;

  fs.writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);
  return configPath;
}

function runWranglerDeploy(cwd, configPath, name) {
  run(resolveWranglerBin(), [
    "deploy",
    "--config",
    configPath,
    ...(dryRun ? ["--dry-run"] : []),
  ], { cwd });
}

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true });
  fs.cpSync(from, to, { recursive: true });
}

function assertFile(filePath, message) {
  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    throw new Error(message);
  }
}

function resolveWranglerBin() {
  const extension = process.platform === "win32" ? ".cmd" : "";
  const localBin = path.join(repoRoot, "node_modules", ".bin", `wrangler${extension}`);
  if (fs.existsSync(localBin)) return localBin;
  return "wrangler";
}

function run(command, args, options = {}) {
  console.log(`\n$ ${command} ${args.join(" ")}`);
  const result = spawnSync(command, args, {
    cwd: options.cwd ?? repoRoot,
    stdio: "inherit",
    env: {
      ...process.env,
      ...(options.env ?? {}),
    },
    shell: process.platform === "win32",
  });
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
}

function getArgValue(name) {
  return process.argv.find((arg) => arg.startsWith(`--${name}=`))?.split("=").slice(1).join("=");
}

function hasFlag(name) {
  return process.argv.includes(`--${name}`);
}

#!/usr/bin/env node
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { memoryAdapter } from "@superfunctions/db/adapters/memory";
import { authfn, authFnPlugins } from "authfn";
import { authFnApiKeyPlugin } from "@authfn/api-keys";
import { authFnEmailOtpPlugin } from "@authfn/email-otp";
import { authFnMultiRegionPlugin } from "@authfn/multi-region";
import { authFnNativeHandoffPlugin } from "@authfn/native-handoff";
import { authFnPasswordPlugin } from "@authfn/password";
import { authFnSocialOAuthPlugin } from "@authfn/social-oauth";
import { authFnTwoFactorPlugin } from "@authfn/two-factor";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, "..", "content", "api");
const outFile = join(outDir, "authfn.json");

const authApp = authfn({
  namespace: "authfn",
  openApi: {
    title: "AuthFn API",
    version: "0.1.1",
  },
  plugins: authFnPlugins(
    authFnPasswordPlugin(),
    authFnEmailOtpPlugin(),
    authFnSocialOAuthPlugin(),
    authFnApiKeyPlugin(),
    authFnTwoFactorPlugin(),
    authFnMultiRegionPlugin(),
    authFnNativeHandoffPlugin(),
  ),
});

const auth = authApp.createServer({
  database: memoryAdapter({ debug: false }),
  pluginRuntime: {
    emailOtp: {
      delivery: { async send() { return { sent: true }; } },
    },
    socialOAuth: {
      providers: {
        google: { clientId: "google-client-id", clientSecret: "google-client-secret" },
        github: { clientId: "github-client-id", clientSecret: "github-client-secret" },
        apple: { clientId: "apple-client-id", clientSecret: "apple-client-secret" },
      },
    },
  },
});

const document = auth.openApi?.();
if (!document) {
  throw new Error("openApi() did not return a document");
}

mkdirSync(outDir, { recursive: true });

const annotated = {
  ...document,
  info: {
    ...(document.info ?? {}),
    title: "AuthFn API",
