      "../../../guide/META.json": '{"title":"Guide"}',
      "../../../pages/about.mdx": "# About",
      "../../../blog/post.md": "---\ntitle: Post\ndate: '2026-01-01'\n---\nPost",
      "../../../api/openapi.json": '{"openapi":"3.0.0","info":{"title":"Example","version":"1"},"paths":{}}',
